    public function fetch_ticker(string $outcome, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcome, $params) {
            /**
             * Fetches the current mid-price and best bid/ask for a single $outcome token.
             * @param $outcome
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/data/get-midpoint-price
             * @see https://docs.polymarket.com/api-reference/market-data/get-order-book
             *
             */
            Async\await($this->load_markets());
            $outcomeObj = $this->outcome($outcome);
            $tokenId = $outcomeObj['id'];
            // Sequential to avoid Promise\all(is_array(lib scope) && array_key_exists(not, lib scope))
            $midpointResponse = Async\await($this->clobPublicGetMidpoint (array( 'token_id' => $tokenId )));
            $bookResponse = Async\await($this->clobPublicGetBook (array( 'token_id' => $tokenId )));
            return $this->parse_ticker(
                array( 'midpoint' => $midpointResponse, 'book' => $bookResponse ),
                $outcomeObj
            );
        }) ();
    }

    public function fetch_tickers(?array $outcomes, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcomes, $params) {
            /**
             * Fetches tickers for multiple outcome tokens sequentially.
             * @param $outcomes
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/data/get-midpoint-price
             *
             */
            Async\await($this->load_markets());
            $targets => stringarray() = $outcomes ? ($outcomes) : is_array($this->outcomes || array()) ? array_keys($this->outcomes || array()) : array();
            $result => Tickers = array();
            for ($outcomeSymbol of $targets) {
                $ticker = Async\await($this->fetch_ticker($outcomeSymbol, $params));
                $result[$outcomeSymbol] = $ticker;
            }
            return $result;
        }) ();
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        /**
         * Parses a combined midpoint . order book response into a unified CCXT Ticker object.
         * @param $ticker
         * @param $market
         */
        $midpointData = $this->safe_value($ticker, 'midpoint', array());
        $bookData = $this->safe_value($ticker, 'book', array());
        $mid = $this->safe_number($midpointData, 'mid');
        $bids = $this->safe_list($bookData, 'bids', array());
        $asks = $this->safe_list($bookData, 'asks', array());
        $bestBid = strlen($bids) ? $this->safe_number($bids[0], 'price') : null;
        $bestAsk = strlen($asks) ? $this->safe_number($asks[0], 'price') : null;
        $symbol = $this->safe_symbol(null, $market);
        $now = $this->milliseconds();
        return $this->safe_ticker(array(
            'symbol' => $symbol,
            'timestamp' => $now,
            'datetime' => $this->iso8601($now),
            'high' => null,
            'low' => null,
            'bid' => $bestBid,
            'bidVolume' => strlen($bids) ? $this->safe_number($bids[0], 'size') : null,
            'ask' => $bestAsk,
            'askVolume' => strlen($asks) ? $this->safe_number($asks[0], 'size') : null,
            'vwap' => null,
            'open' => null,
            'close' => $mid,
            'last' => $mid,
            'previousClose' => null,
            'change' => null,
            'percentage' => null,
            'average' => $mid,
            'baseVolume' => null,
            'quoteVolume' => $market ? $this->safe_number($market['info'], 'volume24h') : null,
            'info' => $ticker,
        ), $market);
    }

    public function fetch_order_book(string $outcome, ?int $limit = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcome, $limit, $params) {
            /**
             * Fetches the CLOB order book for a single $outcome token.
             * @param $outcome
             * @param $limit
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/market-data/get-order-book
             *
             */
            Async\await($this->load_markets());
            $outcomeObj = $this->outcome($outcome);
            $tokenId = $outcomeObj['id'];
            $request = array(
                'token_id' => $tokenId,
            );
            $response = Async\await($this->clobPublicGetBook ($this->extend($request, $params)));
            $timestamp = $this->milliseconds();
            return $this->parse_order_book($response, $outcome, $timestamp, 'bids', 'asks', 'price', 'size');
        }) ();
    }

    public function fetch_ohlcv(string $outcome, $timeframe = '1m', ?int $since = null, ?int $limit = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcome, $timeframe, $since, $limit, $params) {
            /**
             * Fetches price $history ticks for a single $outcome token and maps them to OHLCV format.
             * @param $outcome
             * @param $timeframe
             * @param $since
             * @param $limit
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/markets/get-prices-$history
             *
             */
            Async\await($this->load_markets());
            $outcomeObj = $this->outcome($outcome);
            $tokenId = $outcomeObj['id'];
            $fidelity = $this->safe_string($this->timeframes, $timeframe, '1');
            $request = array(
                'market' => $tokenId,
                'fidelity' => $fidelity,
            );
            if ($since !== null) {
                $request['startTs'] = $this->parse_to_int($since / 1000);
            }
            if ($limit !== null && $since !== null) {
                $tf = $this->parse_timeframe($timeframe);
                $endS = ($since / 1000) . $limit * $tf;
                $nowS = $this->seconds();
                $request['endTs'] = $endS < $nowS ? $endS : $nowS;
            }
            $response = Async\await($this->clobPublicGetPricesHistory ($this->extend($request, $params)));
            $history = $this->safe_list($response, 'history', array());
            return $this->parse_ohlcvs($history, $outcomeObj, $timeframe, $since, $limit);
        }) ();
    }

    public function parse_ohlcv(array $ohlcv, ?array $market = null): array {
        /**
         * Parses a single Polymarket prices-history tick `array( t, p )` into a CCXT OHLCV tuple.
         * @param $ohlcv
         * @param $market
         */
        // Polymarket prices-history tick => array( t => unix_seconds, p => $price )
        $ts = $this->safe_integer($ohlcv, 't');
        $price = $this->safe_number($ohlcv, 'p');
        return array(
            $ts !== null ? $ts * 1000 : null,
            $price,   // open  (raw tick — no OHLCV disaggregation available)
            $price,   // high
            $price,   // low
            $price,   // close
            null, // volume (not provided per-tick)
        );
    }

    public function fetch_trades(string $outcome, ?int $since = null, ?int $limit = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcome, $since, $limit, $params) {
            /**
             * Fetches public trade history for a single $outcome token from the CLOB data endpoint.
             * @param $outcome
             * @param $since
             * @param $limit
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/trade/get-$trades
             *
             */
            Async\await($this->load_markets());
            $outcomeObj = $this->outcome($outcome);
            $tokenId = $outcomeObj['id'];
            $request = array( 'asset_id' => $tokenId );
            if ($limit !== null) {
                $request['limit'] = $limit;
            }
            $response = Async\await($this->clobPublicGetDataTrades ($this->extend($request, $params)));
            $trades = $this->safe_list($response, 'data', array());
            return $this->parse_trades($trades, $outcomeObj, $since, $limit);
        }) ();
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        /**
         * Parses a raw CLOB $trade object into a unified CCXT Trade object.
         * @param $trade
         * @param $market
         */
        $id = $this->safe_string($trade, 'id');
        $timestamp = $this->safe_integer_product($trade, 'timestamp', 1000);
        $price = $this->safe_number($trade, 'price');
        $amount = $this->safe_number($trade, 'size');
        $rawSide = $this->safe_string_lower($trade, 'side');
        $side = ($rawSide === 'buy' || $rawSide === 'sell') ? $rawSide : null;
        $symbol = $this->safe_symbol(null, $market);
        return $this->safe_trade(array(
            'id' => $id,
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $symbol,
            'order' => $this->safe_string($trade, 'orderId'),
            'type' => null,
            'side' => $side,
            'takerOrMaker' => null,
            'price' => $price,
            'amount' => $amount,
            'cost' => null,
            'fee' => null,
        ), $market);
    }

    public function fetch_balance(array $params = array ()): PromiseInterface {
        return Async\async(function () use ($params) {
            /**
             * Fetches the authenticated user's USDC portfolio value from the Data API.
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/core/get-total-value-of-a-users-positions
             *
             */
            $request = array(
                'user' => $this->walletAddress,
            );
            $response = Async\await($this->dataPrivateGetValue ($this->extend($request, $params)));
            return $this->parse_balance($response);
        }) ();
    }

    public function parse_balance(array $response): array {
        /**
         * Parses a portfolio value $response into a CCXT Balances object with a USDC entry.
         * @param $response
         */
        $result = array( 'info' => $response );
        $total = $this->safe_number($response, 'value', $this->safe_number($response, 'total'));
        $result['USDC'] = array(
            'free' => $total,
            'used' => 0,
            'total' => $total,
        );
        return $result;
    }

    public function fetch_positions(?array $outcomes = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcomes, $params) {
            /**
             * Fetches open outcome token $positions for the authenticated user from the Data API.
             * @param $outcomes
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/core/get-current-$positions-for-a-user
             *
             */
            if ($this->walletAddress === null) {
                throw new ArgumentsRequired($this->id . ' walletAddress is required to fetchPositions');
            }
            $request = array(
                'user' => $this->walletAddress,
            );
            $response = Async\await($this->dataPrivateGetPositions ($this->extend($request, $params)));
            $positions = $this->safe_list($response, 'data', array());
            return $this->parse_positions($positions, $outcomes);
        }) ();
    }

    public function parse_position(array $position, ?array $market = null): array {
        /**
         * Parses a raw Data API $position object into a unified CCXT Position object.
         * @param $position
         * @param $market
         */
        $tokenId = $this->safe_string($position, 'asset');
        $marketData = $this->safe_outcome($tokenId, $market);
        $size = $this->safe_number($position, 'size');
        $entryPrice = $this->safe_number($position, 'avgPrice');
        $curPrice = $this->safe_number($position, 'currentPrice');
        // $unrealizedPnl = ($size !== null && $entryPrice !== null && $curPrice !== null)
        //     ? $size * ($curPrice - $entryPrice)
        //     : null;
        return array(
            'id' => $this->safe_string($position, 'id'),
            'symbol' => $marketData['symbol'],
            'timestamp' => null,
            'datetime' => null,
            'contracts' => $size,
            'contractSize' => 1,
            'side' => 'long',
            'notional' => ($size !== null && $curPrice !== null) ? $size * $curPrice : null,
            'leverage' => 1,
            'unrealizedPnl' => null,
            'realizedPnl' => $this->safe_number($position, 'realizedPnl'),
            'collateral' => null,
            'entryPrice' => $entryPrice,
            'markPrice' => $curPrice,
            'liquidationPrice' => null,
            'hedged' => false,
            'maintenanceMargin' => null,
            'maintenanceMarginPercentage' => null,
            'initialMargin' => null,
            'initialMarginPercentage' => null,
            'marginRatio' => null,
            'marginMode' => 'cross',
            'marginType' => 'cross',
            'percentage' => null,
            'info' => $position,
        );
    }

    public function fetch_open_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcome, $since, $limit, $params) {
            /**
             * Fetches open resting $orders for the authenticated user, optionally filtered by $outcome token.
             * @param $outcome
             * @param $since
             * @param $limit
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/trade/get-user-$orders
             *
             */
            $request = array();
            $outcomeObj = null;
            if ($outcome !== null) {
                $outcomeObj = $this->outcome($outcome);
                $request['asset_id'] = $outcomeObj['id'];
            }
            $response = Async\await($this->clobPrivateGetDataOrders ($this->extend($request, $params)));
            $orders = $this->safe_list($response, 'data', array());
            return $this->parse_orders($orders, $outcomeObj, $since, $limit);
        }) ();
