    public function fetch_order(?string $id, ?string $outcome = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($id, $outcome, $params) {
            /**
             * Fetches a single order by ID from the CLOB private data endpoint.
             * @param $id
             * @param symbol
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/trade/get-single-order-by-$id
             *
             */
            $request = array( 'id' => $id );
            $response = Async\await($this->clobPrivateGetDataOrderId ($this->extend($request, $params)));
            return $this->parse_order($response);
        }) ();
    }

    public function parse_order(array $order, ?array $market = null): array {
        /**
         * Parses a raw CLOB $order object into a unified CCXT Order object.
         * @param $order
         * @param $market
         */
        $id = $this->safe_string($order, 'id');
        $tokenId = $this->safe_string($order, 'asset_id');
        $mkt = $this->safe_outcome($tokenId, $market);
        $status = $this->parse_order_status($this->safe_string($order, 'status'));
        $side = $this->safe_string_lower($order, 'side');
        $price = $this->safe_number($order, 'price');
        $amount = $this->safe_number($order, 'original_size');
        $filled = $this->safe_number($order, 'size_matched', 0);
        $ts = $this->safe_integer_product($order, 'created_at', 1000);
        return $this->safe_order(array(
            'id' => $id,
            'clientOrderId' => null,
            'info' => $order,
            'timestamp' => $ts,
            'datetime' => $this->iso8601($ts),
            'lastTradeTimestamp' => null,
            'status' => $status,
            'symbol' => $mkt['symbol'],
            'type' => $this->safe_string_lower($order, 'type', 'limit'),
            'timeInForce' => $this->safe_string($order, 'time_in_force', 'GTC'),
            'postOnly' => null,
            'side' => $side,
            'price' => $price,
            'stopPrice' => null,
            'triggerPrice' => null,
            'average' => null,
            'amount' => $amount,
            'cost' => null,
            'filled' => $filled,
            'remaining' => null,
            'fee' => null,
            'trades' => array(),
        ), $mkt);
    }

    public function parse_order_status(?string $status): ?string {
        /**
         * Maps a Polymarket order $status string to the CCXT unified $status vocabulary.
         * @param $status
         */
        $statuses = array(
            'LIVE' => 'open',
            'MATCHED' => 'closed',
            'CANCELLED' => 'canceled',
            'DELAYED' => 'open',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function create_order(string $outcome, ?string $type, ?string $side, ?float $amount, ?float $price = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcome, $type, $side, $amount, $price, $params) {
            /**
             * Places a limit or market order on the Polymarket CLOB for the given $outcome token.
             * @param $outcome
             * @param $type
             * @param $side
             * @param $amount
             * @param $price
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/trade/post-a-new-order
             *
             */
            Async\await($this->load_markets());
            $outcomeObj = $this->outcome($outcome);
            $tokenId = $outcomeObj['id'];
            $sideStr = strtoupper($side);
            $typeStr = strtoupper($type);
            $request = array(
                'token_id' => $tokenId,
                'price' => $price,
                'size' => $amount,
                'side' => $sideStr,
                'type' => $typeStr,
            );
            $response = Async\await($this->clobPrivatePostOrder ($this->extend($request, $params)));
            return $this->parse_order($response, $outcomeObj);
        }) ();
    }

    public function cancel_order(?string $id, ?string $outcome = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($id, $outcome, $params) {
            /**
             * Cancels a single open order by ID on the Polymarket CLOB.
             * @param $id
             * @param symbol
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/trade/cancel-single-order
             *
             */
            $request = array( 'order_id' => $id );
            $response = Async\await($this->clobPrivateDeleteOrder ($this->extend($request, $params)));
            return $this->parse_order($response);
        }) ();
    }

    public function cancel_all_orders(?string $outcome = null, array $params = array ()): PromiseInterface {
        return Async\async(function () use ($outcome, $params) {
            /**
             * Cancels all open orders on the Polymarket CLOB, optionally scoped to one $outcome token.
             * @param $outcome
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/trade/cancel-all-orders
             *
             */
            $request = array();
            if ($outcome !== null) {
                $outcomeObj = $this->outcome($outcome);
                $request['asset_id'] = $outcomeObj['id'];
            }
            $response = Async\await($this->clobPrivateDeleteOrders ($this->extend($request, $params)));
            return $this->parse_orders($response);
        }) ();
    }

    public function fetch_events(array $queries = [], array $params = array ()): PromiseInterface {
        return Async\async(function () use ($queries, $params) {
            /**
             * Fetches events matching the given search terms via the Gamma public-search endpoint and
             * merges them into $this->events and $this->markets; with no $queries, fetches all active events.
             * Returns the full $this->events dict (all cached events, not just the newly fetched ones).
             * @param $queries
             * @param $params
             *
             * @see https://docs.polymarket.com/api-reference/search/search-markets-events-and-profiles
             *
             */
            $pageSize = $this->safe_integer($params, 'limit', 50);
            $rest = $this->omit($params, array( 'limit' ));
            // For each query => fetch page 1, then all remaining pages in parallel
            $seen = array();
            $rawEvents => anyarray() = array();
            for ($q of $queries) {
                $baseRequest = array( 'q' => $q, 'limit_per_type' => $pageSize, 'events_status' => 'active' );
                $firstRequest = array( 'page' => 1 );
                $first = Async\await($this->gammaPublicGetPublicSearch ($this->extend($firstRequest, $baseRequest, $rest)));
                $firstEvents = $this->safe_list($first, 'events', array());
                $pagination = $this->safe_value($first, 'pagination', array());
                $totalResults = $this->safe_integer($pagination, 'totalResults', strlen($firstEvents));
                $totalPages = (int) ceil($totalResults / $pageSize);
                $remainingPages => numberarray() = array();
                for ($p = 2; $p <= $totalPages; $p++) {
                    $remainingPages[] = $p;
                }
                $restPromises3 => anyarray() = array();
                for ($pi3 = 0; $pi3 < count($remainingPages); $pi3++) {
                    $pageRequest = array( 'page' => $remainingPages[$pi3] );
                    $restPromises3[] = $this->gammaPublicGetPublicSearch ($this->extend($pageRequest, $baseRequest, $rest));
                }
                $restResponses = Async\await(Promise\all($restPromises3));
                $allEvents => anyarray() = ($firstEvents).slice ();
                for ($ri3 = 0; $ri3 < count($restResponses); $ri3++) {
                    $pageEvents3 = $this->safe_list($restResponses[$ri3], 'events', array());
                    for ($ei3 = 0; $ei3 < count($pageEvents3); $ei3++) {
                        $allEvents[] = $pageEvents3[$ei3];
                    }
                }
                for ($rawEvent of $allEvents) {
                    $eventId = $this->safe_string($rawEvent, 'id');
                    if ($eventId && !$seen[$eventId]) {
                        $seen[$eventId] = true;
                        $rawEvents[] = $rawEvent;
                    }
                }
            }
            // Parse and merge into class-level caches
            if (!$this->events) {
                $this->events = array();
            }
            if (!$this->markets) {
                $this->markets = array();
            }
            for ($rawEvent of $rawEvents) {
                $ccxtMarkets = $this->parse_event_to_markets($rawEvent);
                for ($m of $ccxtMarkets) {
                    $this->markets[$m['symbol']] = $m;
                }
                $parsedEvent = $this->parse_event($rawEvent, $ccxtMarkets);
                $eventSlug = $this->safe_string($rawEvent, 'slug');
                if ($eventSlug) {
                    $eventKey = $this->shorten_slugeventSlug;
                    $this->events[$eventKey] = $parsedEvent;
                }
            }
            return is_array($this->events) ? array_values($this->events) : array();
        }) ();
    }

