    public function parse_events(array $rawEvents): array {
        /**
         * Parses an array of raw Gamma event objects into unified CCXT event objects.
         * @param $rawEvents
         */
        $result => anyarray() = array();
        for ($rawEvent of $rawEvents) {
            $result[] = $this->parse_event($rawEvent);
        }
        return $result;
    }

    public function sign(?string $path, mixed $api = 'gamma', $method = 'GET', array $params = array (), ?array $headers = null, ?array $body = null) {
        /**
         * Builds the request URL and attaches HMAC-SHA256 authentication $headers for private endpoints.
         * @param $path
         * @param $api
         * @param $method
         * @param $params
         * @param $headers
         * @param $body
         */
        // $api is either a string ('gamma') or array (['gamma', 'public'])
        $apiGroup = gettype($api) === 'string' ? $api : $api[0];
        $access = gettype($api) === 'string' ? 'public' : $api[1];
        $baseUrls = $this->urls['api'];
        $baseUrl = $this->safe_string($baseUrls, $apiGroup, $baseUrls['gamma']);
        $url = $baseUrl . '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_paramspath);
        $querystring = $this->urlencode($query);
        if ($method === 'GET' && $querystring) {
            $url .= '?' . $querystring;
        }
        $headers = $this->extend(array(
            'Accept' => 'application/json',
            'Content-Type' => 'application/json',
        ), $headers || array());
        if ($access === 'private') {
            $this->check_required_credentials();
            $timestamp = (string) $this->seconds();
            $signature = $this->hmac(
                $this->encode($timestamp . $method . '/' . $path),
                $this->encode($this->secret),
                'sha256',
                'base64'
            );
            $headers = $this->extend($headers, array(
                'POLY_ADDRESS' => $this->walletAddress,
                'POLY_API_KEY' => $this->apiKey,
                'POLY_PASSPHRASE' => $this->password,
                'POLY_SIGNATURE' => $signature,
                'POLY_TIMESTAMP' => $timestamp,
            ));
            if ($method !== 'GET' && $querystring) {
                $body = $query;
            }
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }
